// Listen to server lifecycle events
MinecraftForge.EVENT_BUS.addListener(this::onServerStarting);
MinecraftForge.EVENT_BUS.addListener(this::onServerStarted);
MinecraftForge.EVENT_BUS.addListener(this::onServerStopping);
MinecraftForge.EVENT_BUS.addListener(this::onServerStopped);

private void onServerStarting(ServerStartingEvent event) {
    // Server is starting, just about to begin
    MinecraftServer server = event.getServer();
    // Initialize mod data
}

private void onServerStarted(ServerStartedEvent event) {
    // Server has fully started
    MinecraftServer server = event.getServer();
    // Schedule tasks after server is ready
    server.execute(() -> {
        // Run code on server thread
    });
}

private void onServerStopping(ServerStoppingEvent event) {
    // Server is stopping, save data here
    MinecraftServer server = event.getServer();
    // Save mod data
}

private void onServerStopped(ServerStoppedEvent event) {
    // Server has fully stopped
    // Clean up resources
}
